mapper.select:
SELECT svap_airport_code AS svapAirportCode, svap_aptarea_code AS svapAptareaCode, svap_aptplac_no AS svapAptplacNo, svap_hydrt_pit_no AS svapHydrtPitNo FROM T_SERV_AIRPORT WHERE
svap_airport_code=#{staffAirportCode}
AND svap_aptarea_code=#{staffAptareaCode}

mapper.delete:
DELETE FROM T_SERV_AIRPORT WHERE

    svap_airport_code=#{staffAirportCode}


    AND svap_aptarea_code=#{staffAptareaCode}

AND svap_aptplac_no=#{svapAptplacNo}
AND svap_hydrt_pit_no=#{svapHydrtPitNo}
